func (q *Queries) ReleaseExport(ctx context.Context, arg ReleaseExportParams) (int64, error) {
	result, err := q.db.Exec(ctx, releaseExport, arg.OrgID, arg.ID, arg.Lease)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
